// Package ts carries the TypeScript SDK's files (@kario/sdk) for the kario
// command, which copies them into the projects it creates, bundles KarioUI
// and the test library into apps and tests, and runs apps under Node.js.
package ts

import (
	"embed"
	"fmt"
	"io/fs"
)

// Files: index.d.ts (the module "kario"), ui.d.ts (generated by tools/tsgen)
// and package.json; karioui/ (@kario/ui) and kariotest/ (@kario/test), the
// TypeScript sources bundled into apps and their tests; node/, the module
// "kario" for Node.js (kario run, kario test).
//
//go:embed index.d.ts ui.d.ts package.json karioui/index.ts kariotest/index.ts node/*.mjs
var Files embed.FS

// Modules are the SDK's TypeScript libraries by import name.
var Modules = map[string]string{
	"@kario/ui":   "karioui/index.ts",
	"@kario/test": "kariotest/index.ts",
}

// Source is a library's TypeScript source by its import name.
func Source(module string) ([]byte, error) {
	f, ok := Modules[module]
	if !ok {
		return nil, fmt.Errorf("no module %q in the SDK", module)
	}
	return Files.ReadFile(f)
}

// Node is the runtime for Node.js (node/*.mjs), its files by name.
func Node() (map[string][]byte, error) {
	out := map[string][]byte{}
	entries, err := fs.ReadDir(Files, "node")
	if err != nil {
		return nil, err
	}
	for _, e := range entries {
		raw, err := Files.ReadFile("node/" + e.Name())
		if err != nil {
			return nil, err
		}
		out[e.Name()] = raw
	}
	return out, nil
}
